import{_ as a,o,c as t,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2024Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2024Q3 Ceph社区季度进展报告","date":"2024-09-01T00:00:00.000Z","updated":"2024-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/2024Q3_Ceph社区季度总结.md","filePath":"posts/2024/2024Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),r={name:"posts/2024/2024Q3_Ceph社区季度总结.md"};function i(h,e,l,s,_,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<p>我将基于这29篇会议总结材料，生成一份2024Q3季度的Ceph社区进展报告。</p><hr><h1 id="ceph-社区-2024-q3-季度进展报告" tabindex="-1">Ceph 社区 2024 Q3 季度进展报告 <a class="header-anchor" href="#ceph-社区-2024-q3-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2024 Q3 季度进展报告&quot;">​</a></h1><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>2024年第三季度，Ceph 社区围绕以下几个核心方向展开了密集讨论：</p><p><strong>性能优化与新硬件适配</strong> Erasure Coding（EC）性能优化是本季度最高频的技术议题，贯穿多个会议。随着 NVMe 存储设备的普及，如何充分发挥硬件性能成为核心关切，Crimson 项目的推进正是这一背景下的战略响应。详见 <a href="/VideoSummary/posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.html">Next Generation Erasure Coding Ceph Days London 2024</a>) 和 <a href="/VideoSummary/posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.html">Crimson Project Updates Ceph Days London 2024</a>)。</p><p><strong>Tentacle 版本功能规划</strong> 多个 CDS（Ceph Developer Summit）Tentacle 专题会议密集召开，覆盖 BlueStore、CephFS、RGW、RBD、Dashboard、Cephadm、NVMe-oF、Crimson、Telemetry 等几乎所有子系统，为下一个主要版本奠定功能基线。</p><p><strong>多集群与多站点管理</strong> Dashboard 多集群功能、RGW 多站点复制优化在多个会议中反复出现，反映了用户规模扩大后的运维需求。</p><p><strong>用户体验与易用性</strong> &quot;Ice Pick Initiative&quot;（冰镐倡议）、文档改进、硬件选型指南等议题表明社区在降低使用门槛方面投入了更多精力。详见 <a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-08-21.html">Ceph User + Dev Monthly Meeting2024-08-21</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="_2-1-erasure-coding-下一代优化" tabindex="-1">2.1 Erasure Coding 下一代优化 <a class="header-anchor" href="#_2-1-erasure-coding-下一代优化" aria-label="Permalink to &quot;2.1 Erasure Coding 下一代优化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.html">Next Generation Erasure Coding Ceph Days London 2024</a>) 中，Bill 详细介绍了 EC 性能优化路线：</p><ul><li><strong>部分读取（Partial Read）</strong>：客户端仅读取所需数据块，减少网络带宽和 CPU 开销，已接近合并主分支</li><li><strong>直接读取（Direct Read）</strong>：客户端直接向持有数据的 OSD 发送请求，减少网络跳数</li><li><strong>Apparity Delta写入优化</strong>：通过计算新旧数据的 Delta 并应用于校验码，减少 IOPS</li><li><strong>动态块大小调整</strong>：根据对象大小选择合适的 chunk size，目标在 Tentacle 版本中落地</li></ul><h3 id="_2-2-crimson-osd-进入技术预览" tabindex="-1">2.2 Crimson OSD 进入技术预览 <a class="header-anchor" href="#_2-2-crimson-osd-进入技术预览" aria-label="Permalink to &quot;2.2 Crimson OSD 进入技术预览&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.html">Crimson Project Updates Ceph Days London 2024</a>) 显示 Crimson 已进入技术评审阶段：</p><ul><li>支持多核 CPU，采用 Seastar 框架的异步编程模型</li><li>支持 BlueStore 和 CStore 两种后端</li><li>支持 RBD 工作负载在副本池中运行</li><li>支持快速部署、垃圾回收、快照及 RBD 快照复制</li><li><a href="/VideoSummary/posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.html">Morning Lightning Talks Ceph Days London 2024</a>) 中 IBM 团队分享了 Crimson CPU 利用率测试结果，验证了其性能潜力</li></ul><h3 id="_2-3-nvme-of-网关集成成熟化" tabindex="-1">2.3 NVMe-oF 网关集成成熟化 <a class="header-anchor" href="#_2-3-nvme-of-网关集成成熟化" aria-label="Permalink to &quot;2.3 NVMe-oF 网关集成成熟化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Unlocking_Ceph_s_Potential_with_NVMe_oF_Integration_Ceph_Days_London_2024.html">Unlocking Ceph&#39;s Potential with NVMe-oF Integration Ceph Days London 2024</a>) 展示了 Ceph 与 NVMe-oF 集成的完整进展：</p><ul><li>基于 SPDK 框架实现，支持 TCP、iSCSI、RoCE 等多种网络协议</li><li>网关组（Gateway Group）实现高可用，支持自动故障转移和负载均衡</li><li>支持 NVMe-oF 发现服务，可自动连接所有目标</li><li>计划将 NVMe-oF CLI 集成到 Ceph 主 CLI，并支持 In-Band 消息通知</li></ul><p><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_NVMe.html">CDS Tentacle - NVMe</a>) 进一步讨论了 xcopy 支持、SPDK 动态调度器、用户认证 namespace mask scheme 等增强方向。</p><h3 id="_2-4-rgw-功能扩展" tabindex="-1">2.4 RGW 功能扩展 <a class="header-anchor" href="#_2-4-rgw-功能扩展" aria-label="Permalink to &quot;2.4 RGW 功能扩展&quot;">​</a></h3><p>本季度 RGW 相关会议密集，技术亮点包括：</p><ul><li><strong>Bucket 日志功能</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-28.html">Ceph RGW Refactoring Meeting 2024-08-28</a>) 详细讨论了类 AWS S3 Server Access Logging 的实现，重点保证日志持久性和可靠性</li><li><strong>数据去重（ddop）</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-04.html">Ceph RGW Refactoring Meeting 2024-09-04</a>) 演示了基于 ref 计数和 manifest 共享的去重方案，支持大于 4MB 对象，采用 sharding 并行处理</li><li><strong>端到端追踪（Tracing）</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-21.html">Ceph RGW Refactoring Meeting 2024-08-21</a>) 梳理了从 RGW 前端到 OSD 的完整追踪链路，计划迁移至 OpenTelemetry 协议</li><li><strong>Resharding 优化</strong>：<a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.html">Ceph RGW Refactoring Meeting 2024-09-11</a>) 中改进已合并，最后合并步骤仅阻塞写操作，并计划引入 C++20 协程进一步优化</li><li><strong>云对象恢复（Cloud Restore）</strong>：基本功能已就绪，正在内部审查，讨论了时间戳冲突处理和错误状态返回机制</li></ul><h3 id="_2-5-bluestore-性能深化" tabindex="-1">2.5 BlueStore 性能深化 <a class="header-anchor" href="#_2-5-bluestore-性能深化" aria-label="Permalink to &quot;2.5 BlueStore 性能深化&quot;">​</a></h3><p><a href="./CDS_Tentacle_-_BlueStore.html">CDS Tentacle - BlueStore</a> 会议记录了多项优化工作：</p><ul><li>开发了 OSD 操作日志抓取和重放工具，用于分析真实工作负载下的性能退化</li><li>KVS 线程优化，减少写操作延迟</li><li>研究 RocksDB 管道功能以提高键值排序效率</li><li>Igor 开发了新的分配器，改善内存组织和队列性能</li><li>新压缩算法允许用户在压缩率和 CPU 消耗之间权衡</li></ul><h3 id="_2-6-cephfs-新特性" tabindex="-1">2.6 CephFS 新特性 <a class="header-anchor" href="#_2-6-cephfs-新特性" aria-label="Permalink to &quot;2.6 CephFS 新特性&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_CephFS.html">CDS Tentacle - CephFS</a>) 讨论了多项功能：</p><ul><li><strong>大小写不敏感目录（Case-insensitive Directory）</strong>：通过客户端驱动实现，依赖新增的 alternate name 元数据，提升 Samba 等网关兼容性</li><li><strong>Layout Transformation</strong>：允许用户设置目录期望布局，MDS 逐步迁移数据</li><li><strong>Subvolume 元数据迁移至 SQLite</strong>：提高元数据可靠性和事务支持能力</li><li><strong>快照快速克隆（Fast Clone from Snapshots）</strong>：解决硬链接文件快照问题</li></ul><h3 id="_2-7-dashboard-多集群与carbon-迁移" tabindex="-1">2.7 Dashboard 多集群与Carbon 迁移 <a class="header-anchor" href="#_2-7-dashboard-多集群与carbon-迁移" aria-label="Permalink to &quot;2.7 Dashboard 多集群与Carbon 迁移&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Dashboard.html">CDS Tentacle - Dashboard</a>) 和 <a href="/VideoSummary/posts/2024/Taming_a_Cephalopod_Swarm_Ceph_Days_London_2024.html">Taming a Cephalopod Swarm Ceph Days London 2024</a>) 显示：</p><ul><li>Tentacle 将是首个支持多集群管理的版本，目标支持 50-100 个集群</li><li>引入 SE 管理网关（Admin Gateway），提供单点登录和反向代理，提高安全性</li><li>全面迁移至 Carbon Design System，<a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.html">Ceph User + Dev Monthly Meeting 2024-09-25</a>) 展示了导航栏和数据表的更新效果</li></ul><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><h3 id="_3-1-squid-版本发布" tabindex="-1">3.1 Squid 版本发布 <a class="header-anchor" href="#_3-1-squid-版本发布" aria-label="Permalink to &quot;3.1 Squid 版本发布&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/State_of_the_Cephalopod_Ceph_Days_London_2024.html">State of the Cephalopod Ceph Days London 2024</a>) 确认 Squid 版本已发布，主要亮点包括：RADOS 低延迟快照密集型工作负载优化、Scrub 调度改进、Telemetry 新指标、Dashboard 管理功能增强、Cephadm 协议支持扩展、RBD 快照镜像改进、RGW S3 功能增强、CephFS 代码加固。</p><p><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.html">Ceph RGW Refactoring Meeting 2024-09-11</a>) 记录了 RGW Squid 发布获批，预计一周内完成，期间遇到 Python 依赖变更导致 Ragweed 测试失败的问题。</p><h3 id="_3-2-tentacle-版本规划确立" tabindex="-1">3.2 Tentacle 版本规划确立 <a class="header-anchor" href="#_3-2-tentacle-版本规划确立" aria-label="Permalink to &quot;3.2 Tentacle 版本规划确立&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-25.html">Ceph RGW Refactoring Meeting 2024-09-25</a>) 确认下一个版本号为 19.2.1，并明确了从 squid 分支创建发布分支的流程。多个 CDS Tentacle 专题会议确立了各子系统的功能目标。</p><h3 id="_3-3-centos-stream-生命周期应对" tabindex="-1">3.3 CentOS Stream 生命周期应对 <a class="header-anchor" href="#_3-3-centos-stream-生命周期应对" aria-label="Permalink to &quot;3.3 CentOS Stream 生命周期应对&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-08-07.html">Ceph Developer Monthly2024-08-07</a>) 讨论了 CentOS Stream 生命周期结束对 Ceph 发布计划的影响，团队正在评估替代发行版方案。</p><h3 id="_3-4-upmap-remapper-集成平衡器" tabindex="-1">3.4 Upmap Remapper 集成平衡器 <a class="header-anchor" href="#_3-4-upmap-remapper-集成平衡器" aria-label="Permalink to &quot;3.4 Upmap Remapper 集成平衡器&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.html">Ceph User + Dev Monthly Meeting 2024-09-25</a>) 提出将 upmap remap PG remapper 集成到 Ceph 平衡器模块的设计提案，旨在减少添加/移除 OSD 时的多次 pering 事件，处理集群中大量 misplaced objects。</p><h3 id="_3-5-ceph-与-vmware-集成" tabindex="-1">3.5 Ceph 与 VMware 集成 <a class="header-anchor" href="#_3-5-ceph-与-vmware-集成" aria-label="Permalink to &quot;3.5 Ceph 与 VMware 集成&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/Afternoon_Lightning_Talks_Ceph_Days_London_2024.html">Afternoon Lightning Talks Ceph Days London 2024</a>) 中 IBM 宣布开发了 Ceph 与 VMware 的集成插件，提供部署、扩展和生命周期管理功能，计划后续支持数据路径和数据保护。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><h3 id="_4-1-ceph-days-london-2024" tabindex="-1">4.1 Ceph Days London 2024 <a class="header-anchor" href="#_4-1-ceph-days-london-2024" aria-label="Permalink to &quot;4.1 Ceph Days London 2024&quot;">​</a></h3><p>本季度最重要的社区活动是 <strong>Ceph Days London 2024</strong>，产出了大量技术分享：</p><ul><li>涵盖 Crimson、NVMe-oF、Erasure Coding、硬件选型、HPC 应用、VMware 集成、Sunbeam/OpenStack 集成等主题</li><li><a href="/VideoSummary/posts/2024/State_of_the_Cephalopod_Ceph_Days_London_2024.html">State of the Cephalopod Ceph Days London 2024</a>) 披露社区规模：超过 1300 位贡献者，700,000+ 行代码，146,000+ 次提交，存储足迹接近 1.5 EB</li></ul><h3 id="_4-2-月度开发者与用户会议" tabindex="-1">4.2 月度开发者与用户会议 <a class="header-anchor" href="#_4-2-月度开发者与用户会议" aria-label="Permalink to &quot;4.2 月度开发者与用户会议&quot;">​</a></h3><ul><li><strong>Ceph Developer Monthly 2024-08-07</strong>：讨论了 Crimson 性能建议、CBT 标准化、EC 性能、Manager 模块加载等议题</li><li><strong>Ceph User + Dev Monthly Meeting 2024-08-21</strong>：重点讨论用户体验改进，启动&quot;冰镐倡议&quot;</li><li><strong>Ceph User + Dev Monthly Meeting 2024-09-25</strong>：展示 Stretch 模式禁用功能、Carbon Design System 进展、upmap 集成提案</li></ul><h3 id="_4-3-rgw-重构系列会议" tabindex="-1">4.3 RGW 重构系列会议 <a class="header-anchor" href="#_4-3-rgw-重构系列会议" aria-label="Permalink to &quot;4.3 RGW 重构系列会议&quot;">​</a></h3><p>8月至9月间，RGW 团队连续召开了四次重构专题会议（8-21、8-28、9-04、9-11、9-25），系统性推进 Bucket 日志、数据去重、追踪、Resharding、云恢复、多站点复制等功能。</p><h3 id="_4-4-cds-tentacle-开发者峰会" tabindex="-1">4.4 CDS Tentacle 开发者峰会 <a class="header-anchor" href="#_4-4-cds-tentacle-开发者峰会" aria-label="Permalink to &quot;4.4 CDS Tentacle 开发者峰会&quot;">​</a></h3><p>多个子系统专题峰会密集召开，包括 BlueStore、CephFS、Cephadm、Core RADOS、Crimson、Dashboard、Documentation、NVMe-oF、RBD、RGW、Telemetry，体现了社区对 Tentacle 版本的高度重视。</p><h3 id="_4-5-文档与社区建设" tabindex="-1">4.5 文档与社区建设 <a class="header-anchor" href="#_4-5-文档与社区建设" aria-label="Permalink to &quot;4.5 文档与社区建设&quot;">​</a></h3><p><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Documentation.html">CDS Tentacle - Documentation</a>) 会议中，Ceph 基金会文档负责人 Zack 介绍了文档改进计划，包括新手指南、测试驱动指南、硬件推荐列表和&quot;冰镐计划&quot;（改进在线帮助）。</p><h3 id="_4-6-企业与生态集成" tabindex="-1">4.6 企业与生态集成 <a class="header-anchor" href="#_4-6-企业与生态集成" aria-label="Permalink to &quot;4.6 企业与生态集成&quot;">​</a></h3><ul><li><strong>Bloomberg</strong>：<a href="/VideoSummary/posts/2024/All_things_in_Moderation_Ceph_Days_London_2024.html">All Things in Moderation Ceph Days London 2024</a>) 分享了在 RGW 对象存储上构建集群级 QoS 堆栈的实践，考虑开源该方案</li><li><strong>Canonical/Sunbeam</strong>：<a href="/VideoSummary/posts/2024/Sunbeam_and_Ceph_Sitting_in_a_Tree_Ceph_Days_London_2024.html">Sunbeam and Ceph Sitting in a Tree Ceph Days London 2024</a>) 介绍了基于 Ceph Snap + Juju + Kubernetes 的 OpenStack 部署方案，预计 2023 年底发布稳定版</li><li><strong>Sanger Institute</strong>：<a href="/VideoSummary/posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.html">Morning Lightning Talks Ceph Days London 2024</a>) 分享了基因组研究场景下的 Ceph 使用经验</li></ul><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2024 Q4 将重点推进以下方向：</p><p><strong>Tentacle 版本功能收敛</strong> 各子系统已完成功能规划，Q4 将进入实现和集成阶段。EC 部分读取优化、BlueStore 新分配器、CephFS 大小写不敏感目录等功能有望合并主分支。</p><p><strong>Crimson 扩大测试覆盖</strong> 技术预览版本将扩展测试范围，包括 PG 拆分/合并、RBD 快照复制、动态 CPU 核心分配等，逐步向生产可用迈进。</p><p><strong>RGW 功能落地</strong> Bucket 日志、数据去重（ddop）、端到端追踪、云对象恢复等功能将完成代码审查并推进合并，多站点复制的图形索引方案将进入详细设计。</p><p><strong>Dashboard 多集群 GA</strong> 多集群功能完成性能测试后，将作为 Tentacle 的核心特性发布，Carbon Design System 迁移同步推进。</p><p><strong>NVMe-oF CLI 统一</strong> NVMe-oF CLI 集成到 Ceph 主 CLI 的工作将推进，子系统级访问控制和 namespace屏蔽功能将完善。</p><p><strong>CentOS Stream 替代方案确定</strong> 社区需要在 Q4 明确 Ceph 构建和测试基础设施的操作系统策略，以保障后续版本的发布流程。</p><p><strong>CBT 性能评估标准化</strong><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-08-07.html">Ceph Developer Monthly 2024-08-07</a>) 中提出的 CBT 改进方向（自动化、数据后处理、标准化报告）将推动社区建立统一的性能基准体系。</p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2024/Afternoon_Lightning_Talks_Ceph_Days_London_2024.html">Afternoon Lightning Talks | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/All_things_in_Moderation_Ceph_Days_London_2024.html">All things in Moderation | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tenctacle_-_BlueStore.html">CDS Tenctacle - BlueStore</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_CephFS.html">CDS Tentacle - CephFS</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Cephadm.html">CDS Tentacle - Cephadm</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Core_RADOS.html">CDS Tentacle - Core RADOS</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Crimson.html">CDS Tentacle - Crimson</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Dashboard.html">CDS Tentacle - Dashboard</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Documentation.html">CDS Tentacle - Documentation</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_NVMe.html">CDS Tentacle - NVMe</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_RBD.html">CDS Tentacle - RBD</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_RGW.html">CDS Tentacle - RGW</a>)</li><li><a href="/VideoSummary/posts/2024/CDS_Tentacle_-_Telemetry.html">CDS Tentacle - Telemetry</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_Developer_Monthly_2024-08-07.html">Ceph Developer Monthly | 2024-08-07</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-21.html">Ceph RGW Refactoring Meeting 2024-08-21</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-08-28.html">Ceph RGW Refactoring Meeting 2024-08-28</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-04.html">Ceph RGW Refactoring Meeting 2024-09-04</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.html">Ceph RGW Refactoring Meeting 2024-09-11</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-25.html">Ceph RGW Refactoring Meeting 2024-09-25</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-08-21.html">Ceph User + Dev Monthly Meeting 2024-08-21</a>)</li><li><a href="/VideoSummary/posts/2024/Ceph_User_+_Dev_Monthly_Meeting_2024-09-25.html">Ceph User + Dev Monthly Meeting 2024-09-25</a>)</li><li><a href="/VideoSummary/posts/2024/Crimson_Project_Updates_Ceph_Days_London_2024.html">Crimson Project Updates | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Making_the_Right_Hardware_Choices_Ceph_Days_London_2024.html">Making the Right Hardware Choices | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Morning_Lightning_Talks_Ceph_Days_London_2024.html">Morning Lightning Talks | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.html">Next Generation Erasure Coding | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/State_of_the_Cephalopod_Ceph_Days_London_2024.html">State of the Cephalopod| Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Sunbeam_and_Ceph_Sitting_in_a_Tree_Ceph_Days_London_2024.html">Sunbeam and Ceph Sitting in a Tree | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Taming_a_Cephalopod_Swarm_Ceph_Days_London_2024.html">Taming a Cephalopod Swarm | Ceph Days London 2024</a>)</li><li><a href="/VideoSummary/posts/2024/Unlocking_Ceph_s_Potential_with_NVMe_oF_Integration_Ceph_Days_London_2024.html">Unlocking Ceph&#39;s Potential with NVMe oF Integration | Ceph Days London 2024</a>)</li></ul>',74)])])}const C=a(r,[["render",i]]);export{d as __pageData,C as default};
